using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;
namespace RebirthEntityStudio {
 public static class RebirthBodyMicrodetail {
  public static void PrepareDefault(string path,bool repeat){if(!path.Contains("/BodyGeneratorData/SkinMicrodetail/"))throw new InvalidDataException("Default microdetail setup cannot change a custom texture");var importer=AssetImporter.GetAtPath(path) as TextureImporter;if(importer==null)throw new FileNotFoundException("Skin microdetail texture is missing");var wrap=repeat?TextureWrapMode.Repeat:TextureWrapMode.Clamp;var type=Path.GetFileNameWithoutExtension(path)=="SkinMicroNormal"?TextureImporterType.NormalMap:TextureImporterType.Default;if(importer.textureType==type&&!importer.sRGBTexture&&importer.mipmapEnabled&&importer.textureCompression==TextureImporterCompression.Uncompressed&&importer.wrapMode==wrap&&importer.filterMode==FilterMode.Trilinear)return;importer.textureType=type;importer.sRGBTexture=false;importer.mipmapEnabled=true;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.wrapMode=wrap;importer.filterMode=FilterMode.Trilinear;importer.anisoLevel=2;importer.SaveAndReimport();}
  static Texture2D Load(string guid){if(string.IsNullOrEmpty(guid))return null;var result=AssetDatabase.LoadAssetAtPath<Texture2D>(AssetDatabase.GUIDToAssetPath(guid));if(result==null)throw new FileNotFoundException("Body microdetail texture is missing");return result;}
  static void DataTexture(Texture2D texture,bool repeat){if(texture==null)return;var importer=AssetImporter.GetAtPath(AssetDatabase.GetAssetPath(texture)) as TextureImporter;if(importer==null||importer.textureType!=TextureImporterType.Default||importer.sRGBTexture||!importer.mipmapEnabled||importer.wrapMode!=(repeat?TextureWrapMode.Repeat:TextureWrapMode.Clamp))throw new InvalidDataException("Import microdetail as a linear Default texture with mipmaps; height repeats, region mask clamps");}
  public static void Apply(Material material,BodySurfaceSettings settings){
   if(!material.HasProperty("_MicroStrength")){if(settings.microStrength>0)throw new InvalidDataException("Install the body shader with regional skin microdetail");return;}
   var height=Load(settings.microHeightGuid);var normal=Load(settings.microNormalGuid);var regions=Load(settings.microRegionsGuid);DataTexture(height,true);DataTexture(regions,false);
   if(normal!=null){var importer=AssetImporter.GetAtPath(AssetDatabase.GetAssetPath(normal)) as TextureImporter;if(importer==null||importer.textureType!=TextureImporterType.NormalMap||!importer.mipmapEnabled||importer.wrapMode!=TextureWrapMode.Repeat)throw new InvalidDataException("Skin normal tile requires Normal map import, repeat wrapping and mipmaps");}
   if(settings.microStrength>0&&(height==null||normal==null||regions==null))throw new InvalidDataException("Choose skin height/normal tiles and an anatomical region mask before enabling microdetail");
   material.SetTexture("_MicroNormal",normal);
   material.SetTexture("_MicroHeight",height);material.SetTexture("_MicroRegions",regions);material.SetFloat("_MicroStrength",settings.microStrength);material.SetFloat("_MicroTileSize",settings.microTileSize);material.SetFloat("_MicroRoughness",settings.microRoughness);material.SetVector("_MicroRegionStrength",new Vector4(settings.microTorso,settings.microLimbs,settings.microExtremities,0));
  }
  static string Find(string name)=>AssetDatabase.FindAssets(name+" t:Texture2D").Select(AssetDatabase.GUIDToAssetPath).FirstOrDefault(p=>p.EndsWith("/BodyGeneratorData/SkinMicrodetail/"+name+".png",StringComparison.Ordinal));
  public static BodySurfaceSettings Draw(BodySurfaceSettings current){
   var settings=JsonUtility.FromJson<BodySurfaceSettings>(JsonUtility.ToJson(current));EditorGUILayout.Space();EditorGUILayout.LabelField("Regional skin microdetail",EditorStyles.boldLabel);
   if(GUILayout.Button("Use CC0 skin relief (preview)")){string height=Find("SkinMicroHeight"),normal=Find("SkinMicroNormal"),regions=Find("BodyMicroRegions");if(height==null||normal==null||regions==null)throw new FileNotFoundException("Install CC0 skin height/normal tiles and the body region mask");PrepareDefault(height,true);PrepareDefault(normal,true);PrepareDefault(regions,false);settings.microHeightGuid=AssetDatabase.AssetPathToGUID(height);settings.microNormalGuid=AssetDatabase.AssetPathToGUID(normal);settings.microRegionsGuid=AssetDatabase.AssetPathToGUID(regions);settings.microSourceGuid=AssetDatabase.AssetPathToGUID(Path.GetDirectoryName(height).Replace('\\','/')+"/Source.json");settings.microStrength=.35f;settings.microTileSize=.06f;settings.presetGuid="";return settings;}
   EditorGUI.BeginChangeCheck();var tile=(Texture2D)EditorGUILayout.ObjectField("Skin height tile",Load(settings.microHeightGuid),typeof(Texture2D),false);var mask=(Texture2D)EditorGUILayout.ObjectField("Body regions RGB",Load(settings.microRegionsGuid),typeof(Texture2D),false);
   var normalTile=(Texture2D)EditorGUILayout.ObjectField("Skin normal tile",Load(settings.microNormalGuid),typeof(Texture2D),false);
   settings.microStrength=EditorGUILayout.Slider("Skin relief strength",settings.microStrength,0,1);settings.microTileSize=EditorGUILayout.Slider("Skin tile size (m)",settings.microTileSize,.01f,.2f);settings.microRoughness=EditorGUILayout.Slider("Fine roughness variation",settings.microRoughness,0,1);
   settings.microTorso=EditorGUILayout.Slider("Torso relief",settings.microTorso,0,1);settings.microLimbs=EditorGUILayout.Slider("Limb relief",settings.microLimbs,0,1);settings.microExtremities=EditorGUILayout.Slider("Hand / foot relief",settings.microExtremities,0,1);
   EditorGUILayout.LabelField("Separate authored skin relief, mapped in body space with regional strength. Does not create muscle anatomy, recover reference pores or alter skin colour. Preview quality remains under review.",EditorStyles.wordWrappedMiniLabel);
   if(!EditorGUI.EndChangeCheck())return null;settings.microHeightGuid=tile==null?"":AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(tile));settings.microNormalGuid=normalTile==null?"":AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(normalTile));settings.microRegionsGuid=mask==null?"":AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(mask));if(settings.microHeightGuid!=current.microHeightGuid||settings.microNormalGuid!=current.microNormalGuid)settings.microSourceGuid="";if(tile==null||normalTile==null||mask==null)settings.microStrength=0;settings.Validate();if(!RebirthBodySurface.MatchesPreset(settings,current))settings.presetGuid="";return settings;
  }
  public static void Export(Material material,BodySurfaceSettings settings,string folder){
   if(!string.IsNullOrEmpty(settings.microNormalGuid)){string path=AssetDatabase.GUIDToAssetPath(settings.microNormalGuid),target=folder+"/SkinMicroNormal"+Path.GetExtension(path);if(!AssetDatabase.CopyAsset(path,target))throw new IOException("Could not copy body microdetail normal");material.SetTexture("_MicroNormal",AssetDatabase.LoadAssetAtPath<Texture2D>(target));settings.microNormalGuid=AssetDatabase.AssetPathToGUID(target);}
   if(!string.IsNullOrEmpty(settings.microSourceGuid)){string target=folder+"/SkinMicrodetailSource.json";if(!AssetDatabase.CopyAsset(AssetDatabase.GUIDToAssetPath(settings.microSourceGuid),target))throw new IOException("Could not copy skin microdetail provenance");settings.microSourceGuid=AssetDatabase.AssetPathToGUID(target);}
   foreach(bool height in new[]{true,false}){string guid=height?settings.microHeightGuid:settings.microRegionsGuid;if(string.IsNullOrEmpty(guid))continue;string path=AssetDatabase.GUIDToAssetPath(guid);if(Load(guid)==null)throw new FileNotFoundException("Skin microdetail source missing");string target=folder+"/"+(height?"SkinMicroHeight":"BodyMicroRegions")+Path.GetExtension(path);if(!AssetDatabase.CopyAsset(path,target))throw new IOException("Could not copy body microdetail");material.SetTexture(height?"_MicroHeight":"_MicroRegions",AssetDatabase.LoadAssetAtPath<Texture2D>(target));if(height)settings.microHeightGuid=AssetDatabase.AssetPathToGUID(target);else settings.microRegionsGuid=AssetDatabase.AssetPathToGUID(target);}
  }
 }
}
